"""Original anxiety, trauma and OCD diagnostic distinctions."""
from qbank_authoring import question,ref
rows=[]
GA=ref('NICE adult GAD and panic disorder guideline','https://www.nice.org.uk/guidance/cg113/chapter/Recommendations')
OC=ref('NICE OCD and body dysmorphic disorder guideline','https://www.nice.org.uk/guidance/cg31/chapter/Recommendations')
PT=ref('NICE post-traumatic stress disorder guideline','https://www.nice.org.uk/guidance/ng116/chapter/recommendations')
AS=ref('VA National Center for PTSD: acute stress disorder','https://www.ptsd.va.gov/professional/treat/essentials/acute_stress_disorder.asp')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A patient has recurrent unexpected surges of intense fear with palpitations and dyspnea, followed by 2 months of fear of another attack and avoidance. Appropriate medical/substance assessment is negative. Which diagnosis best fits?', 'Panic disorder',[
 ('Generalized anxiety disorder','GAD involves persistent diffuse worry rather than this defining recurrent-attack pattern.'),('Specific phobia','The attacks are unexpected rather than restricted to one specific feared stimulus.'),('Acute stress disorder','No qualifying trauma-linked acute syndrome is described.')],
 'An attack and a disorder are different levels of diagnosis','**Panic disorder includes recurrent unexpected attacks with persistent concern or maladaptive behavioral change.**',['Panic attacks can also occur within other psychiatric and medical conditions.','Evaluate cardiopulmonary, endocrine and substance causes as indicated.'],'**Assess avoidance and functional burden.**',['Discuss effective psychological and medication options.','Avoid repeated unstructured reassurance without a treatment plan after appropriate medical evaluation.'],[['Attack','Abrupt fear/autonomic episode'],['Disorder','Recurrent unexpected attacks plus persistent consequences'],['Exclusions','Medical/substance explanations']],[GA],style='clinical_scenario')

q('Under DSM-style conventions, an adult has 8 months of difficult-to-control worry about work, health and family with tension, poor concentration and sleep disturbance. Which diagnosis is most consistent?', 'Generalized anxiety disorder',[
 ('Panic disorder','The defining issue is pervasive chronic worry rather than recurrent unexpected discrete attacks.'),('Illness anxiety disorder','The worry spans several domains rather than predominantly disease fear.'),('OCD','No intrusive obsession/ritual cycle is described.')],
 'Clarify the breadth and controllability of worry','**GAD involves persistent excessive anxiety across domains with associated symptoms and impairment.**',['Physical tension and sleep disturbance can dominate presentation.','Exclude substance, medication and medical contributors.'],'**Assess severity, function and coexisting depression.**',['A structured formulation guides stepped psychological or pharmacological treatment.','Avoid diagnosing solely from a screening questionnaire.'],[['Scope','Multiple life domains'],['Course','Persistent'],['Associated findings','Tension, sleep and concentration changes']],[GA],style='clinical_scenario')

q('A patient avoids buses, crowds and being outside alone because escape or help may be difficult if panic-like symptoms occur. Which construct best fits?', 'Agoraphobia',[
 ('Social anxiety disorder','Its central concern is negative evaluation or scrutiny rather than escape/help availability.'),('Specific animal phobia','The fear is not confined to a specific animal or object.'),('OCD contamination avoidance','No contamination obsession or neutralizing ritual is described.')],
 'Ask what the person predicts will happen','**Agoraphobic fear centers on situations where escape or help may be difficult.**',['It can occur with or without panic disorder.','Avoidance and reliance on companions can sustain disability.'],'**Use exposure-based psychological treatment within a collaborative plan.**',['Assess the range of feared situations and safety behaviors.','Do not reduce the diagnosis to fear of open spaces alone.'],[['Agoraphobia','Escape/help concern'],['Social anxiety','Evaluation concern'],['Specific phobia','Circumscribed stimulus']],[GA],style='clinical_scenario')

q('A student avoids presentations and eating in front of others because of fear of humiliation and visible blushing. Which diagnosis is most likely?', 'Social anxiety disorder',[
 ('Agoraphobia','The feared consequence is scrutiny, not principally inability to escape or obtain help.'),('Panic disorder','The symptoms are linked to social evaluation rather than unexpected attacks alone.'),('Delusional disorder','The concern is an anxiety-related fear rather than a described fixed psychotic conviction.')],
 'The feared social meaning defines the syndrome','**Fear of negative evaluation can drive avoidance and anticipatory anxiety.**',['Assess whether the fear is persistent, disproportionate and impairing.','Consider bullying, autism, depression and substance coping as part of the differential/context.'],'**Offer a social-anxiety-specific evidence-based treatment plan.**',['Individual CBT is an important option.','Review functional goals rather than only the intensity of blushing.'],[['Core fear','Negative evaluation'],['Behavior','Avoidance/safety behaviors'],['Treatment goal','Participation and reduced fear']],[ref('NICE social anxiety disorder guideline','https://www.nice.org.uk/guidance/cg159/chapter/recommendations')],style='clinical_scenario')

q('Which pattern most strongly suggests a specific phobia rather than GAD?', 'Persistent disproportionate fear and avoidance restricted mainly to a circumscribed stimulus such as injections',[
 ('Difficult-to-control worry about many everyday domains','This is more typical of GAD.'),('Recurrent unexpected panic attacks with ongoing attack fear','This favors panic disorder.'),('Intrusive contamination thoughts followed by repetitive washing','This favors an OCD pattern.')],
 'Map anxiety to its trigger and maintaining behavior','**Specific phobia is tied to a defined object or situation.**',['A strong normal dislike does not automatically constitute a disorder.','Persistence, disproportionality and functional impact matter.'],'**Use appropriately paced exposure-based treatment.**',['Blood-injection-injury phobia may involve vasovagal responses.','Assess the need for medical procedures and practical support.'],[['Trigger','Circumscribed'],['Impairment','Clinically important'],['Treatment','Exposure-based approach']],[GA])

q('A patient has unwanted repetitive fears of contamination, recognizes them as excessive and washes for hours to reduce distress. Which formulation fits?', 'Obsessions with compulsive washing',[
 ('A pleasurable repetitive hobby','The behavior is driven by distress and an urge to neutralize feared harm.'),('A fixed delusion without any insight','The stem explicitly describes recognition of excessiveness.'),('Generalized worry without compulsions','The intrusive thought and ritual relationship is central.')],
 'Identify the obsession–compulsion cycle','**Compulsions can temporarily reduce distress while maintaining the disorder.**',['Obsessions are intrusive and unwanted thoughts, images or urges.','Insight varies and can be poor in some patients.'],'**Assess time cost, avoidance and impairment.**',['Do not infer dangerous intent merely from an unwanted intrusive thought.','Use OCD-specific assessment and treatment.'],[['Obsession','Intrusive unwanted content'],['Compulsion','Repetitive neutralizing act'],['Cycle','Temporary relief reinforces ritual']],[OC],style='clinical_scenario')

q('Which statement about insight in OCD is correct?', 'Insight ranges from good to absent, so poor insight alone does not automatically establish schizophrenia',[
 ('Every person with OCD recognizes every belief as irrational','Insight varies.'),('Any absent insight excludes OCD by definition','Current diagnostic formulations allow varying insight.'),('A compulsion must always be an externally visible action','Mental rituals can also be compulsions.')],
 'Insight is a dimension rather than a universal gate','**Characterize the intrusive content, ritual function and longitudinal syndrome.**',['Differentiate obsessions from delusions using more than one feature.','Poor insight can make engagement and treatment harder.'],'**Use a careful differential and an OCD-informed treatment plan.**',['Assess comorbid psychosis when other evidence supports it.','Explore mental checking, reassurance seeking and avoidance.'],[['Insight','Variable'],['Compulsions','Behavioral or mental'],['Diagnosis','Whole syndrome']],[OC])

q('After a serious assault, a patient has intrusive memories, avoidance, hypervigilance and negative mood/cognition changes for 4 months with impairment. Which diagnosis is most likely?', 'Post-traumatic stress disorder',[
 ('Acute stress disorder','The duration extends beyond the acute first-month window.'),('Panic disorder as the complete explanation','The symptoms are organized around a traumatic event and broader trauma clusters.'),('Adjustment disorder as the default despite a full trauma syndrome','A more specific qualifying syndrome should be assessed.')],
 'Trauma exposure and symptom clusters define more than general distress','**PTSD includes re-experiencing, avoidance and other persistent trauma-related changes.**',['Assess dissociation, depression, sleep and substance use.','Diagnostic systems differ in how clusters are grouped.'],'**Offer evidence-based trauma-focused care.**',['Establish safety and practical support.','Do not require immediate detailed retelling before a therapeutic plan is agreed.'],[['Exposure','Qualifying trauma'],['Course','Persistent beyond acute window'],['Impact','Functional impairment']],[PT],style='clinical_scenario')

q('Under DSM-5-TR conventions, a patient has a qualifying trauma-related syndrome with intrusion, negative mood, dissociation, avoidance and arousal symptoms beginning 5 days after the event and lasting 2 weeks. Which diagnosis should be assessed?', 'Acute stress disorder',[
 ('PTSD already established solely from this duration','The required PTSD duration has not yet been reached.'),('Normal distress as the only possible formulation regardless of impairment','A qualifying severe acute syndrome can warrant diagnosis and treatment.'),('Schizophrenia because dissociation is present','Dissociation after trauma is not sufficient evidence of schizophrenia.')],
 'Use the early trauma window accurately','**Acute stress disorder applies from three days to one month when the symptom and impairment criteria are met.**',['Not everyone with early distress develops PTSD.','A missing ASD diagnosis does not guarantee protection from later PTSD.'],'**Assess and treat important symptoms with appropriate trauma-focused support.**',['Monitor recovery and reassess persistent symptoms.','Address immediate safety, housing and social needs.'],[['Window','3 days to 1 month'],['Syndrome','Criteria and impairment required'],['Course','May remit or evolve']],[AS],style='clinical_scenario')

q('A patient reports episodes of reliving an assault as if it is happening now, with reduced awareness of the current surroundings. Which phenomenon is described?', 'A trauma-related flashback',[
 ('An ordinary autobiographical memory without altered present experience','The sense of current recurrence and reduced environmental awareness indicate more than ordinary recall.'),('A compulsion performed to neutralize an obsession','No ritualized neutralizing behavior is described.'),('A fixed persecutory delusion established by reliving alone','A flashback is a re-experiencing phenomenon and does not by itself establish primary psychosis.')],
 'Clarify the phenomenology of re-experiencing','**Flashbacks can include dissociative loss of the usual sense of time and place.**',['Severity and awareness vary.','Assess triggers and the effect on safety and daily function.'],'**Use grounding and a trauma-focused treatment plan.**',['Differentiate seizures, substance effects and psychosis when indicated.','Do not interpret every vivid memory as a hallucination of schizophrenia.'],[['Memory','Past event recognized as past'],['Flashback','Sense of current reliving'],['Assessment','Context, awareness and differential']],[PT],style='clinical_scenario')
